import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ClienteList = ({ searchResult }) => {
  const [clientes, setClientes] = useState([]); // Inicializa com um array vazio
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  // Função para carregar clientes com paginação
  const loadClientes = async (page = 1) => {
    try {
      const response = await axios.get(`http://localhost:8080/clientes?page=${page}`);
      setClientes(response.data.content);
      setTotalPages(response.data.totalPages);
    } catch (error) {
      console.error('Erro ao carregar clientes:', error);
    }
  };

  // Efeito para carregar clientes ao montar a página
  useEffect(() => {
    // Verifica se há resultados da busca
    if (!searchResult || searchResult.length === 0) {
      loadClientes(currentPage); // Carregar todos os clientes se não houver busca
    } else {
      setClientes(searchResult); // Exibir o resultado da busca
    }
  }, [searchResult, currentPage]); // Dependências de efeito: searchResult e currentPage

  // Função para navegar entre as páginas
  const goToPage = (page) => {
    setCurrentPage(page);
  };

  return (
    <div className="clientes-list">
      <h2>Lista de Clientes</h2>

      {/* Exibe a lista de clientes */}
      <div className="clientes-container">
        {clientes.length === 0 ? (
          <p>Nenhum cliente encontrado.</p>
        ) : (
          clientes.map((cliente) => (
            <div key={cliente.id} className="cliente-card">
              <h3>{cliente.nome}</h3>
              <p>{cliente.email}</p>
              <p>{cliente.telefone}</p>
            </div>
          ))
        )}
      </div>

      {/* Paginação */}
      {totalPages > 1 && (
        <div className="pagination">
          <button
            disabled={currentPage === 1}
            onClick={() => goToPage(currentPage - 1)}
          >
            Anterior
          </button>
          <span>
            Página {currentPage} de {totalPages}
          </span>
          <button
            disabled={currentPage === totalPages}
            onClick={() => goToPage(currentPage + 1)}
          >
            Próxima
          </button>
        </div>
      )}
    </div>
  );
};

export default ClienteList;
